import json, chess
S="e4 e5 Nf3 Nc6 Nc3 Nf6 Bb5 Bc5 O-O O-O Nxe5 Re8 Nxc6 dxc6 Bc4 b5 Be2 Nxe4 Nxe4 Rxe4 Bf3 Re6 c3 Qd3 b4 Bb6 a4 bxa4 Qxa4 Bd7 Ra2 Rae8 Qa6 Qxf3 gxf3 Rg6+ Kh1 Bh3 Rd1 Bg2+ Kg1 Bxf3+ Kf1 Bg2+ Kg1 Bh3+ Kh1 Bxf2 Qf1 Bxf1 Rxf1 Re2 Ra1 Rh6 d4 Be3".split()
def fen_before(ply):
    b=chess.Board()
    for m in S[:ply]: b.push_san(m)
    return b.fen()
def idx(mv,black): return (mv-1)*2+(1 if black else 0)
def line(a,b_,say={}):
    bd=chess.Board()
    for m in S[:a]: bd.push_san(m)
    out=[]
    for i in range(a,b_):
        mv=bd.push_san(S[i]); out.append({"move":mv.uci(),**({"say":say[i]} if i in say else {})})
    return out
